export const vehicleData = (id) => VEHICLES.find((v) => v.id === id) || VEHICLES[0];
export function tunedStats(data, t) {
  return {
    ...data,
    power: data.power * (1 + t.engine * 0.004),
    torque: data.torque * (1 + t.engine * 0.0035),
    acceleration: data.acceleration * (1 + t.engine * 0.003),
    maxSpeed: data.maxSpeed * (1 + t.engine * 0.0015),
    brakingForce: data.brakingForce * (1 + t.brakes * 0.005),
    grip: data.grip * (1 + t.tires * 0.004) * (1 - t.height * 0.0015),
    driftFactor: data.driftFactor * (1 - t.tires * 0.003),
    steeringAngle: data.steeringAngle * (0.8 + t.steering * 0.004),
    response: 3 + t.steering * 0.09,
    height: data.suspensionHeight + t.height * 0.008,
    stiffness: 20 + t.stiffness * 0.8,
    damping: 3 + t.damping * 0.12,
  };
}
